CREATE OR REPLACE FUNCTION public.zysyr_attach_completed_history_monthly_evidence(p_actor_user_id uuid, p_company_id uuid, p_store_id uuid, p_import_batch_id uuid, p_period_month date, p_original_filename text, p_mime_type text, p_size_bytes bigint, p_sha256 text, p_bucket_id text, p_object_path text, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_saved public.zysyr_history_import_evidence;
  v_link_count integer := 0;
  v_created boolean := false;
begin
  perform zysyr_private.assert_finance_scope(
    p_actor_user_id, p_company_id, p_store_id, 'report.upload'
  );

  if p_mime_type not in ('application/pdf', 'image/jpeg', 'image/png')
     or p_size_bytes not between 1 and 10485760
     or p_sha256 !~ '^[0-9a-f]{64}$'
     or nullif(btrim(p_original_filename), '') is null
     or nullif(btrim(p_object_path), '') is null
     or nullif(btrim(p_reason), '') is null
     or p_period_month <> date_trunc('month', p_period_month)::date then
    raise exception using errcode = '22023', message = 'HISTORY_MONTHLY_ATTACHMENT_INVALID';
  end if;

  if not exists (
    select 1
    from public.zysyr_history_import_batches batch
    where batch.company_id = p_company_id
      and batch.store_id = p_store_id
      and batch.id = p_import_batch_id
      and batch.import_type = 'monthly_profit_loss'
      and batch.status = 'completed'
      and p_period_month between batch.period_start and batch.period_end
  ) then
    raise exception using errcode = 'P0002', message = 'COMPLETED_HISTORY_MONTHLY_REPORT_NOT_FOUND';
  end if;

  if not exists (
    select 1
    from public.zysyr_history_ledger_entries entry
    where entry.company_id = p_company_id
      and entry.store_id = p_store_id
      and entry.import_batch_id = p_import_batch_id
      and entry.entry_type = 'monthly_profit_loss'
      and entry.period_month = p_period_month
      and entry.status = 'posted'
  ) then
    raise exception using errcode = 'P0002', message = 'POSTED_HISTORY_MONTHLY_REPORT_NOT_FOUND';
  end if;

  select evidence.* into v_saved
  from public.zysyr_history_import_evidence evidence
  where evidence.company_id = p_company_id
    and evidence.store_id = p_store_id
    and evidence.import_batch_id = p_import_batch_id
    and evidence.sha256 = p_sha256;

  if v_saved.id is not null and v_saved.period_month <> p_period_month then
    raise exception using errcode = '23505', message = 'HISTORY_MONTHLY_ATTACHMENT_ALREADY_USED_OTHER_MONTH';
  end if;

  if v_saved.id is null then
    insert into public.zysyr_history_import_evidence(
      company_id, store_id, import_batch_id, period_month, evidence_kind,
      original_filename, mime_type, size_bytes, sha256, bucket_id, object_path,
      embedded_asset_count, uploaded_by_user_id
    ) values (
      p_company_id, p_store_id, p_import_batch_id, p_period_month,
      'supporting_document', btrim(p_original_filename), p_mime_type,
      p_size_bytes, p_sha256, coalesce(nullif(btrim(p_bucket_id), ''), 'zysyr-reports'),
      btrim(p_object_path), case when p_mime_type like 'image/%' then 1 else 0 end,
      p_actor_user_id
    ) returning * into v_saved;
    v_created := true;
  end if;

  insert into public.zysyr_history_import_row_evidence(
    company_id, store_id, import_batch_id, import_row_id, evidence_id,
    source_locator, link_level, linked_by_user_id
  )
  select distinct entry.company_id, entry.store_id, entry.import_batch_id,
    entry.import_row_id, v_saved.id,
    'monthly-report:' || to_char(p_period_month, 'YYYY-MM'),
    'bundle_only', p_actor_user_id
  from public.zysyr_history_ledger_entries entry
  where entry.company_id = p_company_id
    and entry.store_id = p_store_id
    and entry.import_batch_id = p_import_batch_id
    and entry.entry_type = 'monthly_profit_loss'
    and entry.period_month = p_period_month
    and entry.status = 'posted'
    and entry.import_row_id is not null
  on conflict do nothing;
  get diagnostics v_link_count = row_count;

  if v_created or v_link_count > 0 then
    insert into public.zysyr_history_import_events(
      company_id, store_id, import_batch_id, action, after_json, reason, actor_user_id
    ) values (
      p_company_id, p_store_id, p_import_batch_id, 'evidence_upload',
      jsonb_build_object(
        'evidence_id', v_saved.id,
        'period_month', p_period_month,
        'filename', v_saved.original_filename,
        'sha256', v_saved.sha256,
        'link_level', 'bundle_only',
        'linked_row_count', v_link_count,
        'scope', 'completed_monthly_report'
      ),
      btrim(p_reason), p_actor_user_id
    );
  end if;

  return jsonb_build_object(
    'evidence', to_jsonb(v_saved),
    'linked_rows', v_link_count,
    'created', v_created,
    'formal_ledger_amount_changed', false
  );
end $function$

CREATE OR REPLACE FUNCTION public.zysyr_attach_history_ledger_evidence(p_actor_user_id uuid, p_company_id uuid, p_store_id uuid, p_ledger_entry_id uuid, p_original_filename text, p_mime_type text, p_size_bytes bigint, p_sha256 text, p_bucket_id text, p_object_path text, p_reason text)
 RETURNS zysyr_history_import_evidence
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_entry public.zysyr_history_ledger_entries;
  v_saved public.zysyr_history_import_evidence;
  v_link_id uuid;
  v_new_evidence boolean := false;
begin
  perform zysyr_private.assert_finance_scope(
    p_actor_user_id, p_company_id, p_store_id, 'expense.create_submit'
  );

  if p_mime_type not in ('application/pdf', 'image/jpeg', 'image/png')
     or p_size_bytes not between 1 and 10485760
     or p_sha256 !~ '^[0-9a-f]{64}$'
     or nullif(btrim(p_original_filename), '') is null
     or nullif(btrim(p_object_path), '') is null
     or nullif(btrim(p_reason), '') is null then
    raise exception using errcode = '22023', message = 'HISTORY_LEDGER_EVIDENCE_INVALID';
  end if;

  select entry.* into v_entry
  from public.zysyr_history_ledger_entries entry
  where entry.company_id = p_company_id
    and entry.store_id = p_store_id
    and entry.id = p_ledger_entry_id
    and entry.entry_type in (
      'monthly_profit_loss', 'salary', 'petty_cash', 'employee_purchase'
    )
    and entry.status = 'posted';
  if v_entry.id is null then
    raise exception using errcode = 'P0002', message = 'HISTORY_LEDGER_ENTRY_NOT_FOUND';
  end if;

  select evidence.* into v_saved
  from public.zysyr_history_import_evidence evidence
  where evidence.company_id = p_company_id
    and evidence.store_id = p_store_id
    and evidence.import_batch_id = v_entry.import_batch_id
    and evidence.sha256 = p_sha256;

  if v_saved.id is null then
    insert into public.zysyr_history_import_evidence(
      company_id, store_id, import_batch_id, period_month, evidence_kind,
      original_filename, mime_type, size_bytes, sha256, bucket_id, object_path,
      embedded_asset_count, uploaded_by_user_id
    ) values (
      p_company_id, p_store_id, v_entry.import_batch_id, v_entry.period_month,
      'supporting_document', btrim(p_original_filename), p_mime_type,
      p_size_bytes, p_sha256,
      coalesce(nullif(btrim(p_bucket_id), ''), 'zysyr-reports'),
      btrim(p_object_path), case when p_mime_type like 'image/%' then 1 else 0 end,
      p_actor_user_id
    ) on conflict do nothing
    returning * into v_saved;
    v_new_evidence := v_saved.id is not null;

    if v_saved.id is null then
      select evidence.* into v_saved
      from public.zysyr_history_import_evidence evidence
      where evidence.company_id = p_company_id
        and evidence.store_id = p_store_id
        and evidence.import_batch_id = v_entry.import_batch_id
        and evidence.sha256 = p_sha256;
    end if;

    if v_new_evidence then
      insert into public.zysyr_history_import_events(
        company_id, store_id, import_batch_id, import_row_id, action,
        after_json, reason, actor_user_id
      ) values (
        p_company_id, p_store_id, v_entry.import_batch_id, v_entry.import_row_id,
        'evidence_upload',
        jsonb_build_object(
          'evidence_id', v_saved.id,
          'ledger_entry_id', v_entry.id,
          'entry_type', v_entry.entry_type,
          'period_month', v_entry.period_month,
          'filename', v_saved.original_filename,
          'sha256', v_saved.sha256,
          'link_level', 'page_confirmed'
        ),
        btrim(p_reason), p_actor_user_id
      );
    end if;
  end if;

  insert into public.zysyr_history_import_row_evidence(
    company_id, store_id, import_batch_id, import_row_id, evidence_id,
    source_locator, link_level, linked_by_user_id
  ) values (
    p_company_id, p_store_id, v_entry.import_batch_id, v_entry.import_row_id,
    v_saved.id, 'manual-upload:' || left(p_sha256, 16), 'page_confirmed',
    p_actor_user_id
  ) on conflict do nothing
  returning id into v_link_id;

  if v_link_id is not null then
    insert into public.zysyr_history_import_events(
      company_id, store_id, import_batch_id, import_row_id, action,
      after_json, reason, actor_user_id
    ) values (
      p_company_id, p_store_id, v_entry.import_batch_id, v_entry.import_row_id,
      'evidence_link',
      jsonb_build_object(
        'evidence_id', v_saved.id,
        'ledger_entry_id', v_entry.id,
        'entry_type', v_entry.entry_type,
        'source_locator', 'manual-upload:' || left(p_sha256, 16),
        'link_level', 'page_confirmed',
        'new_evidence', v_new_evidence
      ),
      btrim(p_reason), p_actor_user_id
    );
  end if;

  return v_saved;
end $function$

CREATE OR REPLACE FUNCTION public.zysyr_confirm_history_import(p_actor_user_id uuid, p_company_id uuid, p_store_id uuid, p_import_batch_id uuid, p_reason text)
 RETURNS zysyr_history_import_batches
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_batch public.zysyr_history_import_batches;
begin
  perform zysyr_private.assert_finance_scope(
    p_actor_user_id, p_company_id, p_store_id, 'expense.create_submit'
  );
  if nullif(btrim(p_reason), '') is null then
    raise exception using errcode = '22023', message = 'HISTORY_IMPORT_CONFIRM_REASON_REQUIRED';
  end if;
  select * into v_batch from public.zysyr_history_import_batches batch
  where batch.company_id = p_company_id and batch.store_id = p_store_id
    and batch.id = p_import_batch_id and batch.status = 'needs_review'
  for update;
  if not found then
    raise exception using errcode = 'P0002', message = 'HISTORY_IMPORT_BATCH_NOT_REVIEWABLE';
  end if;
  if v_batch.invalid_row_count > 0 then
    raise exception using errcode = '23514', message = 'HISTORY_IMPORT_HAS_INVALID_ROWS';
  end if;
  if exists (
    select 1 from public.zysyr_history_import_rows row_item
    where row_item.company_id = p_company_id and row_item.store_id = p_store_id
      and row_item.import_batch_id = p_import_batch_id
      and row_item.review_status <> 'confirmed'
  ) then
    raise exception using errcode = '23514', message = 'HISTORY_IMPORT_HUMAN_REVIEW_INCOMPLETE';
  end if;
  update public.zysyr_history_import_batches set
    status = 'ready', confirmed_by_user_id = p_actor_user_id,
    confirmed_at = now(), confirmation_reason = btrim(p_reason)
  where company_id = p_company_id and id = p_import_batch_id
  returning * into v_batch;
  insert into public.zysyr_history_import_events(
    company_id, store_id, import_batch_id, action, after_json, reason, actor_user_id
  ) values (
    p_company_id, p_store_id, v_batch.id, 'confirm',
    jsonb_build_object('status', v_batch.status,
      'human_review_complete', true, 'row_count', v_batch.raw_row_count),
    btrim(p_reason), p_actor_user_id
  );
  insert into public.zysyr_audit_events(
    company_id, store_id, actor_type, actor_user_id, channel, entity_type,
    entity_id, action, after_json, reason, sensitivity
  ) values (
    p_company_id, p_store_id, 'user', p_actor_user_id, 'import',
    'history_import_batch', v_batch.id, 'confirm',
    jsonb_build_object('status', v_batch.status, 'row_count', v_batch.raw_row_count,
      'human_review_complete', true), btrim(p_reason), 'financial'
  );
  return v_batch;
end $function$

CREATE OR REPLACE FUNCTION public.zysyr_confirm_history_import_month(p_actor_user_id uuid, p_company_id uuid, p_store_id uuid, p_import_batch_id uuid, p_period_month date, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_month date := date_trunc('month', p_period_month)::date;
  v_total integer;
  v_confirmed integer;
  v_invalid integer;
begin
  perform zysyr_private.assert_finance_scope(
    p_actor_user_id, p_company_id, p_store_id, 'expense.create_submit'
  );
  if nullif(btrim(p_reason), '') is null then
    raise exception using errcode = '22023', message = 'HISTORY_IMPORT_MONTH_REVIEW_REASON_REQUIRED';
  end if;
  if not exists (
    select 1 from public.zysyr_history_import_batches batch
    where batch.company_id = p_company_id and batch.store_id = p_store_id
      and batch.id = p_import_batch_id and batch.status = 'needs_review'
      and v_month between batch.period_start and batch.period_end
  ) then
    raise exception using errcode = 'P0002', message = 'HISTORY_IMPORT_MONTH_NOT_REVIEWABLE';
  end if;
  select count(*)::integer,
    count(*) filter (where validation_status = 'invalid')::integer
  into v_total, v_invalid
  from public.zysyr_history_import_rows row_item
  where row_item.company_id = p_company_id and row_item.store_id = p_store_id
    and row_item.import_batch_id = p_import_batch_id
    and coalesce(row_item.corrected_json, row_item.mapped_json)->>'period_month'
      = to_char(v_month, 'YYYY-MM-DD');
  if v_total = 0 then
    raise exception using errcode = 'P0002', message = 'HISTORY_IMPORT_MONTH_HAS_NO_ROWS';
  end if;
  if v_invalid > 0 then
    raise exception using errcode = '23514', message = 'HISTORY_IMPORT_MONTH_HAS_INVALID_ROWS';
  end if;

  update public.zysyr_history_import_rows row_item set
    corrected_json = coalesce(row_item.corrected_json, row_item.mapped_json),
    validation_status = 'valid',
    validation_issues = '[]'::jsonb,
    review_status = 'confirmed',
    reviewed_by_user_id = p_actor_user_id,
    reviewed_at = now(),
    review_note = btrim(p_reason),
    reviewed_snapshot = coalesce(row_item.corrected_json, row_item.mapped_json),
    updated_at = now()
  where row_item.company_id = p_company_id and row_item.store_id = p_store_id
    and row_item.import_batch_id = p_import_batch_id
    and coalesce(row_item.corrected_json, row_item.mapped_json)->>'period_month'
      = to_char(v_month, 'YYYY-MM-DD');
  get diagnostics v_confirmed = row_count;

  update public.zysyr_history_import_batches batch set
    valid_row_count = counts.valid_count,
    warning_row_count = counts.warning_count,
    invalid_row_count = counts.invalid_count
  from (
    select count(*) filter (where validation_status = 'valid')::integer valid_count,
      count(*) filter (where validation_status = 'warning')::integer warning_count,
      count(*) filter (where validation_status = 'invalid')::integer invalid_count
    from public.zysyr_history_import_rows row_item
    where row_item.company_id = p_company_id
      and row_item.import_batch_id = p_import_batch_id
  ) counts
  where batch.company_id = p_company_id and batch.id = p_import_batch_id;

  insert into public.zysyr_history_import_events(
    company_id, store_id, import_batch_id, action, after_json, reason, actor_user_id
  ) values (
    p_company_id, p_store_id, p_import_batch_id, 'month_review',
    jsonb_build_object('period_month', v_month, 'confirmed_rows', v_confirmed,
      'total_rows', v_total, 'review_mode', 'whole_source_sheet'),
    btrim(p_reason), p_actor_user_id
  );
  insert into public.zysyr_audit_events(
    company_id, store_id, actor_type, actor_user_id, channel, entity_type,
    entity_id, action, after_json, reason, sensitivity
  ) values (
    p_company_id, p_store_id, 'user', p_actor_user_id, 'import',
    'history_import_batch', p_import_batch_id, 'month_review',
    jsonb_build_object('period_month', v_month, 'confirmed_rows', v_confirmed,
      'review_mode', 'whole_source_sheet'),
    btrim(p_reason), 'financial'
  );
  return jsonb_build_object('period_month', v_month, 'confirmed_rows', v_confirmed,
    'total_rows', v_total, 'review_mode', 'whole_source_sheet',
    'formal_ledger_written', false);
end $function$

CREATE OR REPLACE FUNCTION public.zysyr_link_history_evidence_month(p_actor_user_id uuid, p_company_id uuid, p_store_id uuid, p_import_batch_id uuid, p_evidence_id uuid, p_period_month date, p_reason text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_count integer := 0;
begin
  perform zysyr_private.assert_finance_scope(
    p_actor_user_id, p_company_id, p_store_id, 'expense.create_submit'
  );
  if nullif(btrim(p_reason), '') is null then
    raise exception using errcode = '22023', message = 'HISTORY_IMPORT_EVIDENCE_REASON_REQUIRED';
  end if;
  if not exists (
    select 1 from public.zysyr_history_import_evidence evidence
    where evidence.company_id = p_company_id and evidence.store_id = p_store_id
      and evidence.import_batch_id = p_import_batch_id and evidence.id = p_evidence_id
      and evidence.period_month = date_trunc('month', p_period_month)::date
  ) then
    raise exception using errcode = 'P0002', message = 'HISTORY_IMPORT_EVIDENCE_SCOPE_MISMATCH';
  end if;
  insert into public.zysyr_history_import_row_evidence(
    company_id, store_id, import_batch_id, import_row_id, evidence_id,
    source_locator, link_level, linked_by_user_id
  )
  select row_item.company_id, row_item.store_id, row_item.import_batch_id,
    row_item.id, p_evidence_id,
    'bundle:' || to_char(date_trunc('month', p_period_month), 'YYYY-MM'),
    'bundle_only', p_actor_user_id
  from public.zysyr_history_import_rows row_item
  where row_item.company_id = p_company_id and row_item.store_id = p_store_id
    and row_item.import_batch_id = p_import_batch_id
    and coalesce(row_item.corrected_json, row_item.mapped_json)->>'period_month'
      = to_char(date_trunc('month', p_period_month), 'YYYY-MM-DD')
  on conflict do nothing;
  get diagnostics v_count = row_count;
  insert into public.zysyr_history_import_events(
    company_id, store_id, import_batch_id, action, after_json, reason, actor_user_id
  ) values (
    p_company_id, p_store_id, p_import_batch_id, 'evidence_link',
    jsonb_build_object('evidence_id', p_evidence_id,
      'period_month', date_trunc('month', p_period_month)::date,
      'link_level', 'bundle_only', 'linked_row_count', v_count),
    btrim(p_reason), p_actor_user_id
  );
  return v_count;
end $function$

CREATE OR REPLACE FUNCTION public.zysyr_link_history_import_evidence(p_actor_user_id uuid, p_company_id uuid, p_store_id uuid, p_import_row_id uuid, p_evidence_id uuid, p_source_locator text, p_reason text)
 RETURNS zysyr_history_import_row_evidence
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_row public.zysyr_history_import_rows;
  v_evidence public.zysyr_history_import_evidence;
  v_saved public.zysyr_history_import_row_evidence;
begin
  perform zysyr_private.assert_finance_scope(
    p_actor_user_id, p_company_id, p_store_id, 'expense.create_submit'
  );
  if nullif(btrim(p_reason), '') is null then
    raise exception using errcode = '22023', message = 'HISTORY_IMPORT_EVIDENCE_REASON_REQUIRED';
  end if;
  select * into v_row from public.zysyr_history_import_rows row_item
  where row_item.company_id = p_company_id and row_item.store_id = p_store_id
    and row_item.id = p_import_row_id;
  select * into v_evidence from public.zysyr_history_import_evidence evidence
  where evidence.company_id = p_company_id and evidence.store_id = p_store_id
    and evidence.id = p_evidence_id;
  if v_row.id is null or v_evidence.id is null
     or v_row.import_batch_id <> v_evidence.import_batch_id then
    raise exception using errcode = 'P0002', message = 'HISTORY_IMPORT_EVIDENCE_SCOPE_MISMATCH';
  end if;
  insert into public.zysyr_history_import_row_evidence(
    company_id, store_id, import_batch_id, import_row_id, evidence_id,
    source_locator, link_level, linked_by_user_id
  ) values (
    p_company_id, p_store_id, v_row.import_batch_id, p_import_row_id, p_evidence_id,
    coalesce(btrim(p_source_locator), ''),
    case when coalesce(btrim(p_source_locator), '') like 'bundle:%'
      then 'bundle_only' else 'page_confirmed' end,
    p_actor_user_id
  ) returning * into v_saved;
  insert into public.zysyr_history_import_events(
    company_id, store_id, import_batch_id, import_row_id, action,
    after_json, reason, actor_user_id
  ) values (
    p_company_id, p_store_id, v_row.import_batch_id, v_row.id, 'evidence_link',
    jsonb_build_object('evidence_id', v_evidence.id,
      'source_locator', v_saved.source_locator), btrim(p_reason), p_actor_user_id
  );
  return v_saved;
end $function$

CREATE OR REPLACE FUNCTION public.zysyr_post_history_import_batch(p_actor_user_id uuid, p_company_id uuid, p_store_id uuid, p_import_batch_id uuid, p_allow_unreviewed boolean, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_batch public.zysyr_history_import_batches;
  v_inserted integer := 0;
  v_imported integer := 0;
  v_warning integer := 0;
  v_unreviewed integer := 0;
begin
  perform zysyr_private.assert_finance_scope(
    p_actor_user_id, p_company_id, p_store_id, 'expense.create_submit'
  );
  if nullif(btrim(p_reason), '') is null then
    raise exception using errcode = '22023', message = 'HISTORY_LEDGER_POST_REASON_REQUIRED';
  end if;

  select * into v_batch
  from public.zysyr_history_import_batches batch
  where batch.company_id = p_company_id and batch.store_id = p_store_id
    and batch.id = p_import_batch_id
  for update;
  if not found then
    raise exception using errcode = 'P0002', message = 'HISTORY_IMPORT_BATCH_NOT_FOUND';
  end if;

  if v_batch.status = 'completed' then
    select count(*)::integer into v_imported
    from public.zysyr_history_ledger_entries entry
    where entry.company_id = p_company_id and entry.store_id = p_store_id
      and entry.import_batch_id = p_import_batch_id;
    return jsonb_build_object(
      'batch_id', p_import_batch_id, 'status', 'completed',
      'inserted_count', 0, 'imported_count', v_imported,
      'already_completed', true, 'formal_ledger_written', v_imported > 0
    );
  end if;
  if v_batch.status not in ('needs_review', 'ready', 'partial', 'failed') then
    raise exception using errcode = '55000', message = 'HISTORY_IMPORT_BATCH_NOT_POSTABLE';
  end if;
  if v_batch.invalid_row_count > 0 or exists (
    select 1 from public.zysyr_history_import_rows row_item
    where row_item.company_id = p_company_id and row_item.store_id = p_store_id
      and row_item.import_batch_id = p_import_batch_id
      and row_item.validation_status = 'invalid'
  ) then
    raise exception using errcode = '23514', message = 'HISTORY_IMPORT_HAS_INVALID_ROWS';
  end if;
  if exists (
    select 1 from public.zysyr_history_import_rows row_item
    where row_item.company_id = p_company_id and row_item.store_id = p_store_id
      and row_item.import_batch_id = p_import_batch_id
      and (
        coalesce(row_item.reviewed_snapshot, row_item.corrected_json, row_item.mapped_json)
          ->>'period_month' is null
        or coalesce(row_item.reviewed_snapshot, row_item.corrected_json, row_item.mapped_json)
          ->>'period_month' !~ '^[0-9]{4}-[0-9]{2}-01$'
      )
  ) then
    raise exception using errcode = '22007', message = 'HISTORY_IMPORT_PERIOD_MONTH_INVALID';
  end if;

  select count(*) filter (where row_item.review_status <> 'confirmed')::integer,
    count(*) filter (where row_item.validation_status = 'warning')::integer
  into v_unreviewed, v_warning
  from public.zysyr_history_import_rows row_item
  where row_item.company_id = p_company_id and row_item.store_id = p_store_id
    and row_item.import_batch_id = p_import_batch_id;
  if v_unreviewed > 0 and not coalesce(p_allow_unreviewed, false) then
    raise exception using errcode = '23514', message = 'HISTORY_IMPORT_HUMAN_REVIEW_INCOMPLETE';
  end if;

  update public.zysyr_history_import_batches set
    status = 'importing',
    confirmed_by_user_id = coalesce(confirmed_by_user_id, p_actor_user_id),
    confirmed_at = coalesce(confirmed_at, now()),
    confirmation_reason = coalesce(confirmation_reason, btrim(p_reason)),
    failure_summary = '{}'::jsonb
  where company_id = p_company_id and id = p_import_batch_id;

  insert into public.zysyr_history_import_events(
    company_id, store_id, import_batch_id, action, after_json, reason, actor_user_id
  ) values (
    p_company_id, p_store_id, p_import_batch_id, 'import_start',
    jsonb_build_object('allow_unreviewed', coalesce(p_allow_unreviewed, false),
      'unreviewed_count', v_unreviewed, 'warning_count', v_warning),
    btrim(p_reason), p_actor_user_id
  );

  with inserted as (
    insert into public.zysyr_history_ledger_entries(
      company_id, store_id, import_batch_id, import_row_id, entry_type,
      period_month, source_sheet, source_locator, source_row_hash,
      posted_payload, current_payload, posted_validation_status,
      posted_validation_issues, posted_review_status, posted_with_warning,
      posted_by_user_id, last_modified_by_user_id
    )
    select row_item.company_id, row_item.store_id, row_item.import_batch_id,
      row_item.id, v_batch.import_type,
      (coalesce(row_item.reviewed_snapshot, row_item.corrected_json, row_item.mapped_json)
        ->>'period_month')::date,
      row_item.source_sheet, row_item.source_locator, row_item.row_hash,
      coalesce(row_item.reviewed_snapshot, row_item.corrected_json, row_item.mapped_json),
      coalesce(row_item.reviewed_snapshot, row_item.corrected_json, row_item.mapped_json),
      row_item.validation_status, row_item.validation_issues, row_item.review_status,
      row_item.validation_status = 'warning' or row_item.review_status <> 'confirmed',
      p_actor_user_id, p_actor_user_id
    from public.zysyr_history_import_rows row_item
    where row_item.company_id = p_company_id and row_item.store_id = p_store_id
      and row_item.import_batch_id = p_import_batch_id
      and row_item.import_status <> 'skipped'
    on conflict (company_id, store_id, import_row_id) do nothing
    returning *
  ), revision_rows as (
    insert into public.zysyr_history_ledger_revisions(
      company_id, store_id, ledger_entry_id, import_batch_id, import_row_id,
      version, action, before_payload, after_payload, reason, actor_user_id
    )
    select entry.company_id, entry.store_id, entry.id, entry.import_batch_id,
      entry.import_row_id, 1, 'post', null, entry.posted_payload,
      btrim(p_reason), p_actor_user_id
    from inserted entry
    returning 1
  )
  select count(*)::integer into v_inserted from revision_rows;

  update public.zysyr_history_import_rows row_item set
    import_status = 'imported', target_business_type = 'history_ledger',
    target_business_id = entry.id, import_error = null,
    imported_at = coalesce(row_item.imported_at, entry.posted_at), updated_at = now()
  from public.zysyr_history_ledger_entries entry
  where row_item.company_id = p_company_id and row_item.store_id = p_store_id
    and row_item.import_batch_id = p_import_batch_id
    and entry.company_id = row_item.company_id and entry.store_id = row_item.store_id
    and entry.import_row_id = row_item.id;

  select count(*)::integer into v_imported
  from public.zysyr_history_import_rows row_item
  where row_item.company_id = p_company_id and row_item.store_id = p_store_id
    and row_item.import_batch_id = p_import_batch_id
    and row_item.import_status = 'imported';
  if v_imported <> v_batch.raw_row_count then
    raise exception using errcode = '23514', message = 'HISTORY_LEDGER_ROW_COUNT_MISMATCH';
  end if;

  update public.zysyr_history_import_batches set
    status = 'completed', imported_row_count = v_imported,
    failed_row_count = 0, completed_at = now(), failure_summary = '{}'::jsonb
  where company_id = p_company_id and id = p_import_batch_id;

  insert into public.zysyr_history_import_events(
    company_id, store_id, import_batch_id, action, after_json, reason, actor_user_id
  ) values (
    p_company_id, p_store_id, p_import_batch_id, 'complete',
    jsonb_build_object('inserted_count', v_inserted, 'imported_count', v_imported,
      'warning_count', v_warning, 'unreviewed_count', v_unreviewed,
      'formal_ledger_written', true),
    btrim(p_reason), p_actor_user_id
  );
  insert into public.zysyr_audit_events(
    company_id, store_id, actor_type, actor_user_id, channel, entity_type,
    entity_id, action, after_json, reason, sensitivity
  ) values (
    p_company_id, p_store_id, 'user', p_actor_user_id, 'import',
    'history_import_batch', p_import_batch_id, 'formal_post',
    jsonb_build_object('inserted_count', v_inserted, 'imported_count', v_imported,
      'warning_count', v_warning, 'unreviewed_count', v_unreviewed),
    btrim(p_reason), 'financial'
  );

  return jsonb_build_object(
    'batch_id', p_import_batch_id, 'status', 'completed',
    'inserted_count', v_inserted, 'imported_count', v_imported,
    'warning_count', v_warning, 'unreviewed_count', v_unreviewed,
    'already_completed', false, 'formal_ledger_written', true
  );
end $function$

CREATE OR REPLACE FUNCTION public.zysyr_register_history_import_evidence(p_actor_user_id uuid, p_company_id uuid, p_store_id uuid, p_import_batch_id uuid, p_period_month date, p_evidence_kind text, p_original_filename text, p_mime_type text, p_size_bytes bigint, p_sha256 text, p_bucket_id text, p_object_path text, p_embedded_asset_count integer, p_reason text)
 RETURNS zysyr_history_import_evidence
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_saved public.zysyr_history_import_evidence;
  v_link_count integer := 0;
begin
  perform zysyr_private.assert_finance_scope(
    p_actor_user_id, p_company_id, p_store_id, 'expense.create_submit'
  );
  if p_evidence_kind not in ('voucher_bundle', 'supporting_document')
     or p_mime_type not in (
       'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
       'application/pdf', 'image/jpeg', 'image/png'
     ) or p_size_bytes not between 1 and 52428800 or p_sha256 !~ '^[0-9a-f]{64}$'
     or p_embedded_asset_count not between 0 and 2000
     or nullif(btrim(p_original_filename), '') is null
     or nullif(btrim(p_object_path), '') is null
     or nullif(btrim(p_reason), '') is null then
    raise exception using errcode = '22023', message = 'HISTORY_IMPORT_EVIDENCE_INVALID';
  end if;
  if not exists (
    select 1 from public.zysyr_history_import_batches batch
    where batch.company_id = p_company_id and batch.store_id = p_store_id
      and batch.id = p_import_batch_id and batch.status in ('needs_review', 'ready')
      and date_trunc('month', p_period_month)::date between batch.period_start and batch.period_end
  ) then raise exception using errcode = 'P0002', message = 'HISTORY_IMPORT_BATCH_NOT_FOUND'; end if;
  insert into public.zysyr_history_import_evidence(
    company_id, store_id, import_batch_id, period_month, evidence_kind,
    original_filename, mime_type, size_bytes, sha256, bucket_id, object_path,
    embedded_asset_count, uploaded_by_user_id
  ) values (
    p_company_id, p_store_id, p_import_batch_id, date_trunc('month', p_period_month)::date,
    p_evidence_kind, btrim(p_original_filename), p_mime_type, p_size_bytes,
    p_sha256, coalesce(nullif(btrim(p_bucket_id), ''), 'zysyr-reports'),
    btrim(p_object_path), p_embedded_asset_count, p_actor_user_id
  ) returning * into v_saved;
  insert into public.zysyr_history_import_row_evidence(
    company_id, store_id, import_batch_id, import_row_id, evidence_id,
    source_locator, link_level, linked_by_user_id
  )
  select row_item.company_id, row_item.store_id, row_item.import_batch_id,
    row_item.id, v_saved.id,
    'bundle:' || to_char(date_trunc('month', p_period_month), 'YYYY-MM'),
    'bundle_only', p_actor_user_id
  from public.zysyr_history_import_rows row_item
  where row_item.company_id = p_company_id and row_item.store_id = p_store_id
    and row_item.import_batch_id = p_import_batch_id
    and coalesce(row_item.corrected_json, row_item.mapped_json)->>'period_month'
      = to_char(date_trunc('month', p_period_month), 'YYYY-MM-DD')
  on conflict do nothing;
  get diagnostics v_link_count = row_count;
  insert into public.zysyr_history_import_events(
    company_id, store_id, import_batch_id, action, after_json, reason, actor_user_id
  ) values (
    p_company_id, p_store_id, p_import_batch_id, 'evidence_upload',
    jsonb_build_object('evidence_id', v_saved.id, 'period_month', v_saved.period_month,
      'filename', v_saved.original_filename, 'sha256', v_saved.sha256,
      'embedded_asset_count', v_saved.embedded_asset_count,
      'link_level', 'bundle_only', 'linked_row_count', v_link_count),
    btrim(p_reason), p_actor_user_id
  );
  return v_saved;
end $function$

CREATE OR REPLACE FUNCTION public.zysyr_reverse_history_ledger_entry(p_actor_user_id uuid, p_company_id uuid, p_store_id uuid, p_ledger_entry_id uuid, p_reason text)
 RETURNS zysyr_history_ledger_entries
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_before public.zysyr_history_ledger_entries;
  v_after public.zysyr_history_ledger_entries;
begin
  perform zysyr_private.assert_finance_scope(
    p_actor_user_id, p_company_id, p_store_id, 'expense.create_submit'
  );
  if nullif(btrim(p_reason), '') is null then
    raise exception using errcode = '22023', message = 'HISTORY_LEDGER_REVERSAL_REASON_REQUIRED';
