  );
  update public.zysyr_history_ledger_entries set
    status = 'reversed', version = v_before.version + 1,
    last_modified_by_user_id = p_actor_user_id, last_modified_at = now(),
    reversed_by_user_id = p_actor_user_id, reversed_at = now(),
    reversal_reason = btrim(p_reason)
  where company_id = p_company_id and id = v_before.id
  returning * into v_after;

  insert into public.zysyr_history_import_events(
    company_id, store_id, import_batch_id, import_row_id, action,
    before_json, after_json, reason, actor_user_id
  ) values (
    p_company_id, p_store_id, v_before.import_batch_id, v_before.import_row_id,
    'ledger_reverse', jsonb_build_object('status', v_before.status,
      'version', v_before.version), jsonb_build_object('status', v_after.status,
      'version', v_after.version), btrim(p_reason), p_actor_user_id
  );
  insert into public.zysyr_audit_events(
    company_id, store_id, actor_type, actor_user_id, channel, entity_type,
    entity_id, action, before_json, after_json, reason, sensitivity
  ) values (
    p_company_id, p_store_id, 'user', p_actor_user_id, 'import',
    'history_ledger_entry', v_after.id, 'reverse',
    jsonb_build_object('status', v_before.status, 'version', v_before.version),
    jsonb_build_object('status', v_after.status, 'version', v_after.version),
    btrim(p_reason), 'financial'
  );
  return v_after;
end $function$

CREATE OR REPLACE FUNCTION public.zysyr_revise_history_ledger_entry(p_actor_user_id uuid, p_company_id uuid, p_store_id uuid, p_ledger_entry_id uuid, p_current_payload jsonb, p_reason text)
 RETURNS zysyr_history_ledger_entries
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_before public.zysyr_history_ledger_entries;
  v_after public.zysyr_history_ledger_entries;
begin
  perform zysyr_private.assert_finance_scope(
    p_actor_user_id, p_company_id, p_store_id, 'expense.create_submit'
  );
  if jsonb_typeof(p_current_payload) <> 'object'
     or nullif(btrim(p_reason), '') is null then
    raise exception using errcode = '22023', message = 'HISTORY_LEDGER_REVISION_INVALID';
  end if;
  select * into v_before
  from public.zysyr_history_ledger_entries entry
  where entry.company_id = p_company_id and entry.store_id = p_store_id
    and entry.id = p_ledger_entry_id and entry.status = 'posted'
  for update;
  if not found then
    raise exception using errcode = 'P0002', message = 'HISTORY_LEDGER_ENTRY_NOT_EDITABLE';
  end if;
  if p_current_payload->>'period_month' is distinct from to_char(v_before.period_month, 'YYYY-MM-DD') then
    raise exception using errcode = '23514', message = 'HISTORY_LEDGER_PERIOD_IMMUTABLE';
  end if;
  if p_current_payload = v_before.current_payload then
    raise exception using errcode = '22023', message = 'HISTORY_LEDGER_NO_CHANGES';
  end if;

  insert into public.zysyr_history_ledger_revisions(
    company_id, store_id, ledger_entry_id, import_batch_id, import_row_id,
    version, action, before_payload, after_payload, reason, actor_user_id
  ) values (
    p_company_id, p_store_id, v_before.id, v_before.import_batch_id,
    v_before.import_row_id, v_before.version + 1, 'revise',
    v_before.current_payload, p_current_payload, btrim(p_reason), p_actor_user_id
  );
  update public.zysyr_history_ledger_entries set
    current_payload = p_current_payload, version = v_before.version + 1,
    last_modified_by_user_id = p_actor_user_id, last_modified_at = now()
  where company_id = p_company_id and id = v_before.id
  returning * into v_after;

  insert into public.zysyr_history_import_events(
    company_id, store_id, import_batch_id, import_row_id, action,
    before_json, after_json, reason, actor_user_id
  ) values (
    p_company_id, p_store_id, v_before.import_batch_id, v_before.import_row_id,
    'ledger_revise', v_before.current_payload, v_after.current_payload,
    btrim(p_reason), p_actor_user_id
  );
  insert into public.zysyr_audit_events(
    company_id, store_id, actor_type, actor_user_id, channel, entity_type,
    entity_id, action, before_json, after_json, reason, sensitivity
  ) values (
    p_company_id, p_store_id, 'user', p_actor_user_id, 'import',
    'history_ledger_entry', v_after.id, 'revise',
    v_before.current_payload, v_after.current_payload, btrim(p_reason), 'financial'
  );
  return v_after;
end $function$

CREATE OR REPLACE FUNCTION public.zysyr_revise_history_monthly_cell(p_actor_user_id uuid, p_company_id uuid, p_store_id uuid, p_ledger_entry_id uuid, p_after_amount numeric, p_reason text)
 RETURNS zysyr_history_ledger_entries
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_before public.zysyr_history_ledger_entries;
  v_after public.zysyr_history_ledger_entries;
  v_payload jsonb;
  v_unlock public.zysyr_monthly_cell_unlock_requests;
  v_cell_kind text;
  v_label text;
begin
  perform zysyr_private.assert_finance_scope(
    p_actor_user_id, p_company_id, p_store_id, 'confirmed_finance.adjust'
  );
  if p_after_amount is null
     or abs(p_after_amount) > 99999999999999.9999
     or nullif(btrim(p_reason), '') is null then
    raise exception using errcode = '22023', message = 'HISTORY_MONTHLY_CELL_CHANGE_INVALID';
  end if;

  select * into v_before
  from public.zysyr_history_ledger_entries entry
  where entry.company_id = p_company_id
    and entry.store_id = p_store_id
    and entry.id = p_ledger_entry_id
    and entry.entry_type = 'monthly_profit_loss'
    and entry.status = 'posted'
  for update;
  if not found then
    raise exception using errcode = 'P0002', message = 'HISTORY_MONTHLY_CELL_NOT_EDITABLE';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(
    p_company_id::text || ':' || p_store_id::text || ':' || v_before.period_month::text, 0
  ));
  v_cell_kind := coalesce(v_before.current_payload->>'cell_kind', '');
  v_label := coalesce(v_before.current_payload->>'label', '');
  if v_cell_kind = 'formula' or v_label ~ '(编号|序号|员工号)' or v_label ~ '^[[:space:]]*(小计|合计|总计|盈亏)([[:space:]]*[/／·]|[[:space:]]*$)' then
    raise exception using errcode = '55000', message = 'HISTORY_MONTHLY_CELL_EDIT_FORBIDDEN';
  end if;
  if coalesce(v_before.current_payload->>'amount', '') !~ '^-?[0-9]+([.][0-9]+)?$' then
    raise exception using errcode = '55000', message = 'HISTORY_MONTHLY_CELL_AMOUNT_MISSING';
  end if;
  if round((v_before.current_payload->>'amount')::numeric, 4) = round(p_after_amount, 4) then
    raise exception using errcode = '22023', message = 'HISTORY_MONTHLY_CELL_AMOUNT_UNCHANGED';
  end if;

  if zysyr_private.period_is_locked(p_company_id, p_store_id, v_before.period_month) then
    select * into v_unlock
    from public.zysyr_monthly_cell_unlock_requests request
    where request.company_id = p_company_id
      and request.store_id = p_store_id
      and request.period_month = v_before.period_month
      and request.requested_by_user_id = p_actor_user_id
      and request.status = 'approved'
    order by request.decided_at asc
    limit 1 for update;
    if not found then
      raise exception using errcode = '55000', message = 'MONTHLY_UNLOCK_APPROVAL_REQUIRED';
    end if;
  end if;

  v_payload := jsonb_set(
    v_before.current_payload, '{amount}', to_jsonb(round(p_after_amount, 4)), true
  );
  insert into public.zysyr_history_ledger_revisions (
    company_id, store_id, ledger_entry_id, import_batch_id, import_row_id,
    version, action, before_payload, after_payload, reason, actor_user_id
  ) values (
    p_company_id, p_store_id, v_before.id, v_before.import_batch_id,
    v_before.import_row_id, v_before.version + 1, 'revise_monthly_amount',
    v_before.current_payload, v_payload, btrim(p_reason), p_actor_user_id
  );
  update public.zysyr_history_ledger_entries set
    current_payload = v_payload, version = v_before.version + 1,
    last_modified_by_user_id = p_actor_user_id, last_modified_at = clock_timestamp()
  where company_id = p_company_id and id = v_before.id
  returning * into v_after;

  insert into public.zysyr_history_import_events (
    company_id, store_id, import_batch_id, import_row_id, action,
    before_json, after_json, reason, actor_user_id
  ) values (
    p_company_id, p_store_id, v_before.import_batch_id, v_before.import_row_id,
    'ledger_revise_monthly_amount', v_before.current_payload, v_after.current_payload,
    btrim(p_reason), p_actor_user_id
  );
  insert into public.zysyr_audit_events (
    company_id, store_id, actor_type, actor_user_id, channel, entity_type,
    entity_id, action, before_json, after_json, reason, sensitivity
  ) values (
    p_company_id, p_store_id, 'user', p_actor_user_id, 'api',
    'history_monthly_cell', v_after.id, 'amount_change',
    jsonb_build_object('amount', v_before.current_payload->'amount',
      'period_month', v_before.period_month,
      'cell_address', v_before.current_payload->>'cell_address'),
    jsonb_build_object('amount', v_after.current_payload->'amount',
      'period_month', v_after.period_month,
      'cell_address', v_after.current_payload->>'cell_address',
      'version', v_after.version, 'unlock_request_id', v_unlock.id),
    btrim(p_reason), 'financial'
  );
  if v_unlock.id is not null then
    update public.zysyr_monthly_cell_unlock_requests
    set status = 'consumed', consumed_at = clock_timestamp()
    where company_id = p_company_id and id = v_unlock.id;
  end if;
  return v_after;
end
$function$

CREATE OR REPLACE FUNCTION public.zysyr_stage_history_import(p_actor_user_id uuid, p_company_id uuid, p_store_id uuid, p_import_type text, p_source_filename text, p_source_mime_type text, p_source_size_bytes bigint, p_source_sha256 text, p_source_bucket_id text, p_source_object_path text, p_source_store_label text, p_target_store_label text, p_period_start date, p_period_end date, p_rows jsonb, p_source_warnings jsonb, p_preview_summary jsonb, p_reason text)
 RETURNS zysyr_history_import_batches
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_batch public.zysyr_history_import_batches;
  v_row jsonb;
  v_raw jsonb;
  v_mapped jsonb;
  v_issues jsonb;
  v_status text;
  v_sheet text;
  v_row_number integer;
  v_row_hash text;
  v_count integer := 0;
  v_valid_count integer := 0;
  v_warning_count integer := 0;
  v_invalid_count integer := 0;
begin
  perform zysyr_private.assert_finance_scope(
    p_actor_user_id, p_company_id, p_store_id, 'expense.create_submit'
  );
  if p_import_type not in ('monthly_profit_loss', 'salary', 'petty_cash', 'employee_purchase')
     or p_source_mime_type not in (
       'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
       'application/vnd.openxmlformats-officedocument.wordprocessingml.document'
     )
     or p_source_size_bytes not between 1 and 52428800
     or p_source_sha256 !~ '^[0-9a-f]{64}$'
     or p_period_start is null or p_period_end is null or p_period_start > p_period_end
     or jsonb_typeof(p_rows) <> 'array' or jsonb_array_length(p_rows) not between 1 and 5000
     or jsonb_typeof(coalesce(p_source_warnings, '[]'::jsonb)) <> 'array'
     or jsonb_typeof(coalesce(p_preview_summary, '{}'::jsonb)) <> 'object'
     or nullif(btrim(p_source_filename), '') is null
     or nullif(btrim(p_source_object_path), '') is null
     or nullif(btrim(p_target_store_label), '') is null
     or nullif(btrim(p_reason), '') is null then
    raise exception using errcode = '22023', message = 'HISTORY_IMPORT_INPUT_INVALID';
  end if;

  -- Validate every preview row before creating the batch so the count invariant
  -- is true at insert time. The following insert loop repeats this extraction
  -- because the original payload must remain byte-for-byte auditable.
  for v_row in select value from jsonb_array_elements(p_rows) loop
    v_count := v_count + 1;
    v_raw := coalesce(v_row->'raw', '{}'::jsonb);
    v_mapped := coalesce(v_row->'mapped', '{}'::jsonb);
    v_issues := coalesce(v_row->'issues', '[]'::jsonb);
    v_status := coalesce(v_row->>'validation_status', 'invalid');
    v_sheet := nullif(btrim(v_row->>'source_sheet'), '');
    v_row_number := coalesce((v_row->>'source_row_number')::integer, v_count);
    if jsonb_typeof(v_raw) <> 'object' or jsonb_typeof(v_mapped) <> 'object'
       or jsonb_typeof(v_issues) <> 'array' or v_status not in ('valid', 'warning', 'invalid')
       or v_sheet is null or v_row_number < 1 then
      raise exception using errcode = '22023', message = 'HISTORY_IMPORT_ROW_INVALID';
    end if;
    if v_status = 'valid' then
      v_valid_count := v_valid_count + 1;
    elsif v_status = 'warning' then
      v_warning_count := v_warning_count + 1;
    else
      v_invalid_count := v_invalid_count + 1;
    end if;
  end loop;

  insert into public.zysyr_history_import_batches(
    company_id, store_id, import_type, source_filename, source_mime_type,
    source_size_bytes, source_sha256, source_bucket_id, source_object_path,
    source_store_label, target_store_label, period_start, period_end,
    raw_row_count, valid_row_count, warning_row_count, invalid_row_count,
    source_warnings, preview_summary, reason, created_by_user_id
  ) values (
    p_company_id, p_store_id, p_import_type, btrim(p_source_filename),
    p_source_mime_type, p_source_size_bytes, p_source_sha256,
    coalesce(nullif(btrim(p_source_bucket_id), ''), 'zysyr-reports'),
    btrim(p_source_object_path), nullif(btrim(p_source_store_label), ''),
    btrim(p_target_store_label), date_trunc('month', p_period_start)::date,
    date_trunc('month', p_period_end)::date, jsonb_array_length(p_rows),
    v_valid_count, v_warning_count, v_invalid_count,
    coalesce(p_source_warnings, '[]'::jsonb), coalesce(p_preview_summary, '{}'::jsonb),
    btrim(p_reason), p_actor_user_id
  ) returning * into v_batch;

  v_count := 0;
  for v_row in select value from jsonb_array_elements(p_rows) loop
    v_count := v_count + 1;
    v_raw := coalesce(v_row->'raw', '{}'::jsonb);
    v_mapped := coalesce(v_row->'mapped', '{}'::jsonb);
    v_issues := coalesce(v_row->'issues', '[]'::jsonb);
    v_status := coalesce(v_row->>'validation_status', 'invalid');
    v_sheet := nullif(btrim(v_row->>'source_sheet'), '');
    v_row_number := coalesce((v_row->>'source_row_number')::integer, v_count);
    if jsonb_typeof(v_raw) <> 'object' or jsonb_typeof(v_mapped) <> 'object'
       or jsonb_typeof(v_issues) <> 'array' or v_status not in ('valid', 'warning', 'invalid')
       or v_sheet is null or v_row_number < 1 then
      raise exception using errcode = '22023', message = 'HISTORY_IMPORT_ROW_INVALID';
    end if;
    v_row_hash := coalesce(nullif(v_row->>'row_hash', ''),
      pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(v_raw::text, 'UTF8')), 'hex'));
    insert into public.zysyr_history_import_rows(
      company_id, store_id, import_batch_id, source_sheet, source_row_number,
      source_locator, row_hash, raw_json, mapped_json, validation_status, validation_issues
    ) values (
      p_company_id, p_store_id, v_batch.id, v_sheet, v_row_number,
      coalesce(nullif(btrim(v_row->>'source_locator'), ''), v_sheet || '!ROW' || v_row_number::text),
      v_row_hash, v_raw, v_mapped, v_status, v_issues
    );
  end loop;

  insert into public.zysyr_history_import_events(
    company_id, store_id, import_batch_id, action, after_json, reason, actor_user_id
  ) values (
    p_company_id, p_store_id, v_batch.id, 'stage',
    jsonb_build_object('source_sha256', v_batch.source_sha256,
      'raw_row_count', v_batch.raw_row_count, 'valid_row_count', v_batch.valid_row_count,
      'warning_row_count', v_batch.warning_row_count, 'invalid_row_count', v_batch.invalid_row_count),
    btrim(p_reason), p_actor_user_id
  );
  insert into public.zysyr_audit_events(
    company_id, store_id, actor_type, actor_user_id, channel, entity_type,
    entity_id, action, after_json, reason, sensitivity
  ) values (
    p_company_id, p_store_id, 'user', p_actor_user_id, 'import',
    'history_import_batch', v_batch.id, 'stage',
    jsonb_build_object('import_type', v_batch.import_type,
      'source_sha256', v_batch.source_sha256, 'row_count', v_batch.raw_row_count),
    btrim(p_reason), 'financial'
  );
  return v_batch;
exception when unique_violation then
  raise exception using errcode = '23505', message = 'HISTORY_IMPORT_SOURCE_ALREADY_STAGED';
end $function$

CREATE OR REPLACE FUNCTION zysyr_private.assert_finance_scope(target_user_account_id uuid, target_company_id uuid, target_store_id uuid, target_capability_code text)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if not zysyr_private.account_is_finance_in_scope(
    target_user_account_id, target_company_id, target_store_id
  ) or not zysyr_private.account_has_capability(
    target_user_account_id, target_company_id, target_store_id, target_capability_code
  ) then
    raise exception using errcode = '42501', message = 'FINANCE_SCOPE_FORBIDDEN';
  end if;
end
$function$

CREATE OR REPLACE FUNCTION zysyr_private.reset_history_import_review_after_correction()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if (
    new.corrected_json is distinct from old.corrected_json
    or new.validation_status is distinct from old.validation_status
    or new.validation_issues is distinct from old.validation_issues
  ) and new.review_status is not distinct from old.review_status then
    new.review_status := 'pending';
    new.reviewed_by_user_id := null;
    new.reviewed_at := null;
    new.review_note := null;
    new.reviewed_snapshot := null;
  end if;
  return new;
end $function$
